  assert.equal(source.indexOf(after,op.afterOffset+after.length),-1,'OWNER190_QA_RECONCILIATION_EXACT_REVIEWED_RAW_SPAN_UNIQUE');
  assert.deepEqual(source.subarray(op.afterOffset,op.afterOffset+after.length),after,'OWNER190_QA_RECONCILIATION_EXACT_REVIEWED_RAW_SPAN');
